INSERT INTO content_collections (site_id,code,name,content_type,sort,page_size,active,created_at,updated_at) SELECT id,'DEMO_LATEST_NEWS','Demo Latest News','NEWS','PUBLISHED_DESC',12,'T',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM sites WHERE code='default' ON CONFLICT (site_id,code) DO UPDATE SET name=EXCLUDED.name,content_type=EXCLUDED.content_type,sort=EXCLUDED.sort,page_size=EXCLUDED.page_size,active='T',updated_at=CURRENT_TIMESTAMP;
INSERT INTO content_collections (site_id,code,name,content_type,sort,page_size,active,created_at,updated_at) SELECT id,'DEMO_AI_AGENT_BLOG','Demo AI Agent Blog','BLOG','PUBLISHED_DESC',12,'T',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM sites WHERE code='default' ON CONFLICT (site_id,code) DO UPDATE SET name=EXCLUDED.name,content_type=EXCLUDED.content_type,sort=EXCLUDED.sort,page_size=EXCLUDED.page_size,active='T',updated_at=CURRENT_TIMESTAMP;
INSERT INTO pages (site_id,title,slug,content,page_type,status,homepage,menu_visible,template_id,created_at,updated_at) SELECT s.id,'News','news',NULL,'BLOCK','PUBLISHED','F','T',(SELECT id FROM templates WHERE code='STANDARD'),CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM sites s WHERE s.code='default' ON CONFLICT (site_id,slug) DO UPDATE SET title='News',page_type='BLOCK',status='PUBLISHED',updated_at=CURRENT_TIMESTAMP;
INSERT INTO pages (site_id,title,slug,content,page_type,status,homepage,menu_visible,template_id,created_at,updated_at) SELECT s.id,'Blog','blog',NULL,'BLOCK','PUBLISHED','F','T',(SELECT id FROM templates WHERE code='STANDARD'),CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM sites s WHERE s.code='default' ON CONFLICT (site_id,slug) DO UPDATE SET title='Blog',page_type='BLOCK',status='PUBLISHED',updated_at=CURRENT_TIMESTAMP;
INSERT INTO page_blocks (page_id,block_type,title,sort_order,visible,config_json,created_at,updated_at) SELECT p.id,'CONTENT_COLLECTION','News',0,'T','{"collectionCode":"DEMO_LATEST_NEWS","displayMode":"CARDS","paginationEnabled":true}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM pages p JOIN sites s ON s.id=p.site_id WHERE s.code='default' AND p.slug='news' AND NOT EXISTS (SELECT 1 FROM page_blocks b WHERE b.page_id=p.id AND b.block_type='CONTENT_COLLECTION');
INSERT INTO page_blocks (page_id,block_type,title,sort_order,visible,config_json,created_at,updated_at) SELECT p.id,'CONTENT_COLLECTION','Blog',0,'T','{"collectionCode":"DEMO_AI_AGENT_BLOG","displayMode":"CARDS","paginationEnabled":true}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM pages p JOIN sites s ON s.id=p.site_id WHERE s.code='default' AND p.slug='blog' AND NOT EXISTS (SELECT 1 FROM page_blocks b WHERE b.page_id=p.id AND b.block_type='CONTENT_COLLECTION');
INSERT INTO menu_items (menu_id,parent_id,page_id,target_type,title,sort_order,visible,created_at,updated_at) SELECT m.id,NULL,p.id,'PAGE','News',100,'T',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM menus m JOIN sites s ON s.id=m.site_id JOIN pages p ON p.site_id=s.id AND p.slug='news' WHERE s.code='default' AND m.code='MAIN' AND NOT EXISTS (SELECT 1 FROM menu_items i WHERE i.menu_id=m.id AND i.parent_id IS NULL AND i.title='News');
INSERT INTO menu_items (menu_id,parent_id,page_id,target_type,title,sort_order,visible,created_at,updated_at) SELECT m.id,NULL,p.id,'PAGE','Blog',101,'T',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM menus m JOIN sites s ON s.id=m.site_id JOIN pages p ON p.site_id=s.id AND p.slug='blog' WHERE s.code='default' AND m.code='MAIN' AND NOT EXISTS (SELECT 1 FROM menu_items i WHERE i.menu_id=m.id AND i.parent_id IS NULL AND i.title='Blog');
